//! Build-time kernel registry, generated by `build.rs`.
//!
//! The `mcc` precompilation pipeline compiles every `kernels/*.cu` into an ELF
//! fatbin and emits this module listing each `(source id, fatbin bytes)` pair.
//! On hosts without `mcc` — and on every non-Linux target — the registry is
//! empty and the backend reports a device error at run time instead of
//! compiling kernels it does not have (docs/musa-backend-plan.md §5.6).

include!(concat!(env!("OUT_DIR"), "/registry.rs"));
